Building REST APIs is a fundamental skill for modern web developers. In this tutorial, we&rsquo;ll create a complete REST API using Node.js and Express, perfect for beginners who want to understand backend development.
What You&rsquo;ll Learn By the end of this tutorial, you&rsquo;ll have built a functional REST API that can:
Handle GET, POST, PUT, and DELETE requests Manage data with proper error handling Implement middleware for logging and validation Structure your project for scalability Prerequisites Before we start, make sure you have:
Node.js installed (version 14 or higher) Basic understanding of JavaScript A text editor (VS Code recommended) Postman or similar API testing tool Setting Up the Project First, let&rsquo;s create a new project and install the necessary dependencies:
mkdir my-first-api cd my-first-api npm init -y npm install express cors helmet dotenv npm install -D nodemon Project Structure Let&rsquo;s organize our project with a clean structure:
my-first-api/ ├── src/ │ ├── controllers/ │ ├── middleware/ │ ├── models/ │ └── routes/ ├── .env ├── .gitignore ├── package.json └── server.js Creating the Basic Server Start by creating the main server file:
// server.js const express = require(&#39;express&#39;); const cors = require(&#39;cors&#39;); const helmet = require(&#39;helmet&#39;); require(&#39;dotenv&#39;).config(); const app = express(); const PORT = process.env.PORT || 3000; // Middleware app.use(helmet()); // Security headers app.use(cors()); // Enable CORS app.use(express.json()); // Parse JSON bodies // Basic route app.get(&#39;/&#39;, (req, res) =&gt; { res.json({ message: &#39;Welcome to my first API!&#39; }); }); // Start server app.listen(PORT, () =&gt; { console.log(`Server running on port ${PORT}`); }); Building the API Routes Let&rsquo;s create a simple books API to demonstrate CRUD operations:
// src/routes/books.js const express = require(&#39;express&#39;); const router = express.Router(); // Sample data (in a real app, this would be a database) let books = [ { id: 1, title: &#39;The JavaScript Way&#39;, author: &#39;Baptiste Pesquet&#39;, year: 2018 }, { id: 2, title: &#39;Clean Code&#39;, author: &#39;Robert Martin&#39;, year: 2008 } ]; // GET all books router.get(&#39;/&#39;, (req, res) =&gt; { res.json(books); }); // GET book by ID router.get(&#39;/:id&#39;, (req, res) =&gt; { const book = books.find(b =&gt; b.id === parseInt(req.params.id)); if (!book) { return res.status(404).json({ error: &#39;Book not found&#39; }); } res.json(book); }); // POST new book router.post(&#39;/&#39;, (req, res) =&gt; { const { title, author, year } = req.body; if (!title || !author || !year) { return res.status(400).json({ error: &#39;Missing required fields&#39; }); } const newBook = { id: books.length + 1, title, author, year: parseInt(year) }; books.push(newBook); res.status(201).json(newBook); }); // PUT update book router.put(&#39;/:id&#39;, (req, res) =&gt; { const bookIndex = books.findIndex(b =&gt; b.id === parseInt(req.params.id)); if (bookIndex === -1) { return res.status(404).json({ error: &#39;Book not found&#39; }); } const { title, author, year } = req.body; books[bookIndex] = { ...books[bookIndex], title, author, year }; res.json(books[bookIndex]); }); // DELETE book router.delete(&#39;/:id&#39;, (req, res) =&gt; { const bookIndex = books.findIndex(b =&gt; b.id === parseInt(req.params.id)); if (bookIndex === -1) { return res.status(404).json({ error: &#39;Book not found&#39; }); } books.splice(bookIndex, 1); res.status(204).send(); }); module.exports = router; Adding Middleware Create a simple logging middleware:
// src/middleware/logger.js const logger = (req, res, next) =&gt; { const timestamp = new Date().toISOString(); console.log(`${timestamp} - ${req.method} ${req.path}`); next(); }; module.exports = logger; Putting It All Together Update your server.js to use the routes and middleware:
// server.js (updated) const express = require(&#39;express&#39;); const cors = require(&#39;cors&#39;); const helmet = require(&#39;helmet&#39;); const logger = require(&#39;./src/middleware/logger&#39;); const booksRouter = require(&#39;./src/routes/books&#39;); require(&#39;dotenv&#39;).config(); const app = express(); const PORT = process.env.PORT || 3000; // Middleware app.use(helmet()); app.use(cors()); app.use(express.json()); app.use(logger); // Routes app.use(&#39;/api/books&#39;, booksRouter); app.get(&#39;/&#39;, (req, res) =&gt; { res.json({ message: &#39;Welcome to my first API!&#39;, endpoints: { books: &#39;/api/books&#39; } }); }); app.listen(PORT, () =&gt; { console.log(`Server running on port ${PORT}`); }); Testing Your API You can test your API using these curl commands:
# Get all books curl http://localhost:3000/api/books # Get a specific book curl http://localhost:3000/api/books/1 # Create a new book curl -X POST http://localhost:3000/api/books \ -H &#34;Content-Type: application/json&#34; \ -d &#39;{&#34;title&#34;:&#34;Node.js in Action&#34;,&#34;author&#34;:&#34;Alex Young&#34;,&#34;year&#34;:2017}&#39; # Update a book curl -X PUT http://localhost:3000/api/books/1 \ -H &#34;Content-Type: application/json&#34; \ -d &#39;{&#34;title&#34;:&#34;Updated Title&#34;,&#34;author&#34;:&#34;Updated Author&#34;,&#34;year&#34;:2023}&#39; # Delete a book curl -X DELETE http://localhost:3000/api/books/1 Next Steps Congratulations! You&rsquo;ve built your first REST API. Here are some improvements you can make:
Add a Database - Replace the in-memory array with MongoDB or PostgreSQL Authentication - Implement JWT-based authentication Validation - Use libraries like Joi for input validation Testing - Write unit tests with Jest Documentation - Use Swagger for API documentation Conclusion Building REST APIs with Node.js and Express is straightforward once you understand the fundamentals. This tutorial covered the basics, but there&rsquo;s much more to explore in backend development.
Keep practicing, and don&rsquo;t hesitate to ask questions in our Code &amp; Coffee meetups!
